"""Compile the PostgreSQL baseline from schema.sql plus foreign keys."""

from __future__ import annotations

import re
from pathlib import Path

from .constraints import FOREIGN_KEYS

SCHEMA = Path(__file__).with_name("schema.sql")


def postgres_schema() -> str:
    sql = SCHEMA.read_text(encoding="utf-8")
    sql = sql.replace(
        "INTEGER PRIMARY KEY AUTOINCREMENT",
        "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
    )
    sql = re.sub(r"\bREAL\b", "DOUBLE PRECISION", sql)
    alters = []
    for table, column, ref_table, ref_col in FOREIGN_KEYS:
        name = f"fk_{table}_{column}"[:63]
        alters.append(
            f"ALTER TABLE {table} ADD CONSTRAINT {name} "
            f"FOREIGN KEY ({column}) REFERENCES {ref_table}({ref_col})"
        )
    alters.append(
        "ALTER TABLE payments ADD CONSTRAINT payments_amount_positive CHECK (amount_paise > 0)"
    )
    alters.append(
        "ALTER TABLE deposits ADD CONSTRAINT deposits_amount_positive CHECK (amount_paise > 0)"
    )
    return sql.rstrip() + "\n\n" + ";\n".join(alters) + ";\n"
